pub fn modelCount() usize { return 12 * 40; }

pub fn sampleArgv(gpa: std.mem.Allocator) ![]const []const u8 {
    return try g.runtime_shard_0.local_model_0_0_argv(gpa);
}

test "llama product all runtime shards" {
    const gpa = std.testing.allocator;
    const list = try listLocalModels(gpa);
    defer gpa.free(list);
    try std.testing.expect(std.mem.indexOf(u8, list, "local-0-0") != null);
    try std.testing.expect(std.mem.indexOf(u8, list, "local-11-39") != null);
    try std.testing.expectEqual(@as(usize, 480), modelCount());
}
